document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".settings-nav-btn"),t=document.querySelectorAll(".settings-panel");e.forEach(n=>{n.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),t.forEach(e=>e.classList.remove("active")),n.classList.add("active"),document.getElementById(`panel-${n.dataset.panel}`)?.classList.add("active")})});const n=document.getElementById("personalForm");n?.addEventListener("submit",e=>{e.preventDefault();const t=document.getElementById("personalSuccess");t.hidden=!1,setTimeout(()=>{t.hidden=!0},3e3)});const d=document.getElementById("securityForm");d?.addEventListener("submit",e=>{e.preventDefault();const t=document.getElementById("newPassword"),n=document.getElementById("confirmPassword"),o=document.getElementById("confirmPasswordError");if(t.value&&t.value!==n.value)return void(o.textContent="كلمتا المرور غير متطابقتين");o.textContent="";const c=document.getElementById("securitySuccess");c.hidden=!1,d.reset(),setTimeout(()=>{c.hidden=!0},3e3)}),document.getElementById("deleteAccountBtn")?.addEventListener("click",function(){window.confirm("هل أنت متأكد من رغبتك في حذف حسابك نهائيًا؟ لا يمكن التراجع عن هذا الإجراء.")&&(window.location.href="login.html")})});